function countSteppingNumbers(low, high) {
  const result = [];
  if (low === 0) {
    result.push(0);
  }
  const queue = [1, 2, 3, 4, 5, 6, 7, 8, 9];
  let front = 0;
  while (front < queue.length) {
    const num = queue[front];
    front++;
    if (num > high) {
      break;
    }
    if (num >= low) {
      result.push(num);
    }
    const last = num % 10;
    if (last > 0) {
      queue.push(num * 10 + last - 1);
    }
    if (last < 9) {
      queue.push(num * 10 + last + 1);
    }
  }
  return result;
}

