function countSteppingNumbers(low, high) {
  const found = [];
  const grow = (value) => {
    if (value > high) return;
    if (value >= low) found.push(value);
    const digit = value % 10;
    for (const next of [digit - 1, digit + 1]) {
      if (next >= 0 && next <= 9) grow(value * 10 + next);
    }
  };
  if (low <= 0) found.push(0);
  for (let start = 1; start <= 9; start++) grow(start);
  return found.sort((a, b) => a - b);
}

