function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const MAX = 2000000000;
  if (size === 'large') {
    const low = rand() < 0.4 ? 0 : int(0, 1000000000);
    const high = rand() < 0.5 ? MAX : int(Math.max(low, 1000000000), MAX);
    return [low, high];
  }
  const roll = rand();
  if (roll < 0.15) {
    const value = int(0, 12);
    return [value, value];
  }
  if (roll < 0.6) {
    const low = int(0, 150);
    return [low, low + int(0, 250)];
  }
  if (roll < 0.85) {
    const low = int(0, 100000);
    return [low, Math.min(MAX, low + int(0, 20000))];
  }
  const low = int(MAX - 1100000000, MAX);
  return [low, Math.min(MAX, low + int(0, 5000000))];
